udentComboBox.SelectedItem == null)        {            _statusTextBlock.Text = "Hiba: Válasszon diákot!";            _statusTextBlock.Foreground = Brushes.Red;            return;        }        if (_subjectComboBox.SelectedItem == null)        {            _statusTextBlock.Text = "Hiba: Válasszon tantárgyat!";            _statusTextBlock.Foreground = Brushes.Red;            return;        }        if (!int.TryParse(_gradeValueTextBox.Text, out int gradeValue) || gradeValue < 1 || gradeValue > 5)        {            _statusTextBlock.Text = "Hiba: Az érdemjegy 1 és 5 közötti szám kell legyen!";            _statusTextBlock.Foreground = Brushes.Red;            return;        }        var selectedStudent = _students?[_studentComboBox.SelectedIndex];        var selectedSubject = _subjects?[_subjectComboBox.SelectedIndex];                if (selectedStudent == null || selectedSubject == null)        {            _statusTextBlock.Text = "Hiba: A kiválasztott diák vagy tantárgy érvénytelen.";            _statusTextBlock.Foreground = Brushes.Red;            return;        }        var newGrade = new Grade        {            StudentId = selectedStudent.Id,            SubjectId = selectedSubject.Id,            Value = gradeValue,            Date = DateTime.Now        };                _context.AddGrade(selectedStudent.Id, newGrade);                _statusTextBlock.Text = "Sikeres beírás!";        _statusTextBlock.Foreground = Brushes.Green;                _gradeValueTextBox.Text = "";        _subjectComboBox.SelectedIndex = -1;    }}